-- Schema of database 'hh_healthcenter' (PostgreSQL 16), generated by Hibernate from the JPA entities.
-- Reference only: the services create/update these tables automatically (spring.jpa.hibernate.ddl-auto=update).

CREATE TABLE public.centre_facilities (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    category character varying(30) NOT NULL,
    centre_id bigint NOT NULL,
    centre_name character varying(255),
    name character varying(255) NOT NULL,
    notes character varying(500),
    quantity integer,
    status character varying(20),
    CONSTRAINT centre_facilities_category_check CHECK (((category)::text = ANY ((ARRAY['LABORATORY'::character varying, 'PHARMACY'::character varying, 'LABOUR_ROOM'::character varying, 'X_RAY'::character varying, 'AMBULANCE'::character varying, 'INPATIENT_BEDS'::character varying, 'VACCINATION_COLD_CHAIN'::character varying, 'OPERATION_THEATRE'::character varying, 'TELEMEDICINE'::character varying, 'DRINKING_WATER'::character varying, 'POWER_BACKUP'::character varying, 'TOILETS'::character varying])::text[]))),
    CONSTRAINT centre_facilities_status_check CHECK (((status)::text = ANY ((ARRAY['AVAILABLE'::character varying, 'UNDER_MAINTENANCE'::character varying, 'UNAVAILABLE'::character varying])::text[])))
);
ALTER TABLE public.centre_facilities ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.centre_facilities_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.centre_services (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    available boolean,
    available_days character varying(255),
    category character varying(30) NOT NULL,
    centre_id bigint NOT NULL,
    centre_name character varying(255),
    description character varying(500),
    fee double precision,
    name character varying(255) NOT NULL,
    CONSTRAINT centre_services_category_check CHECK (((category)::text = ANY ((ARRAY['GENERAL_OPD'::character varying, 'MATERNAL_HEALTH'::character varying, 'CHILD_HEALTH'::character varying, 'IMMUNIZATION'::character varying, 'FAMILY_PLANNING'::character varying, 'COMMUNICABLE_DISEASE'::character varying, 'NCD'::character varying, 'DIAGNOSTICS'::character varying, 'EMERGENCY'::character varying, 'DENTAL'::character varying, 'EYE_CARE'::character varying, 'MENTAL_HEALTH'::character varying])::text[])))
);
ALTER TABLE public.centre_services ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.centre_services_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.health_centres (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    address character varying(255),
    bed_capacity integer,
    block character varying(255),
    code character varying(20),
    district character varying(255),
    email character varying(255),
    in_charge_name character varying(255),
    latitude double precision,
    longitude double precision,
    name character varying(120) NOT NULL,
    phone character varying(255),
    population_covered integer,
    status character varying(15),
    type character varying(20) NOT NULL,
    village character varying(255) NOT NULL,
    CONSTRAINT health_centres_status_check CHECK (((status)::text = ANY ((ARRAY['OPERATIONAL'::character varying, 'LIMITED'::character varying, 'CLOSED'::character varying])::text[]))),
    CONSTRAINT health_centres_type_check CHECK (((type)::text = ANY ((ARRAY['SUB_CENTRE'::character varying, 'PHC'::character varying, 'CHC'::character varying, 'DISPENSARY'::character varying, 'WELLNESS_CENTRE'::character varying])::text[])))
);
ALTER TABLE public.health_centres ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.health_centres_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.health_workers (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    centre_id bigint NOT NULL,
    centre_name character varying(255),
    email character varying(255),
    joining_date date,
    name character varying(255) NOT NULL,
    phone character varying(255),
    qualification character varying(255),
    registration_number character varying(255),
    role character varying(20) NOT NULL,
    specialization character varying(255),
    status character varying(15),
    villages_covered character varying(255),
    CONSTRAINT health_workers_role_check CHECK (((role)::text = ANY ((ARRAY['DOCTOR'::character varying, 'NURSE'::character varying, 'ANM'::character varying, 'ASHA'::character varying, 'PHARMACIST'::character varying, 'LAB_TECHNICIAN'::character varying, 'MPW'::character varying, 'SANITATION_WORKER'::character varying, 'ADMIN_STAFF'::character varying])::text[]))),
    CONSTRAINT health_workers_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'ON_LEAVE'::character varying, 'INACTIVE'::character varying])::text[])))
);
ALTER TABLE public.health_workers ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
